application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#18222d; --muted:#71808e; --line:#dce5e9; --mint:#b7eadb; --deep:#176b60; --paper:#fff; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:#f3f8f7; font-family:'DM Sans',Arial,sans-serif; }
body:before { content:""; position:fixed; width:420px; height:420px; border-radius:50%; background:#dff5ee; top:-160px; right:-100px; z-index:-1; }
.app-shell { width:min(850px, calc(100% - 36px)); margin:0 auto; padding:62px 0 70px; }
.hero { margin-bottom:30px; }
.eyebrow,.result-label { color:var(--deep); font-size:11px; font-weight:700; letter-spacing:2px; }
h1 { font-family:'Space Grotesk',Arial,sans-serif; font-size:clamp(34px,6vw,54px); letter-spacing:-2px; margin:10px 0 10px; line-height:1.05; }
.hero p { color:var(--muted); margin:0; font-size:16px; }
.quiz-card { background:var(--paper); border:1px solid #e1ebea; border-radius:22px; padding:8px 34px 28px; box-shadow:0 18px 45px rgba(24,65,61,.08); }
.question { padding:27px 0 30px; border-bottom:1px solid var(--line); }
.question-heading { display:flex; gap:17px; align-items:flex-start; }
.question-number { color:#52a796; font-family:'Space Grotesk',sans-serif; font-weight:700; font-size:14px; padding-top:3px; }
h2 { font-family:'Space Grotesk',Arial,sans-serif; font-size:19px; margin:0; line-height:1.35; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:11px; margin:20px 0 0 32px; }
.option { position:relative; display:flex; align-items:center; gap:10px; border:1px solid var(--line); border-radius:11px; padding:13px 14px; cursor:pointer; color:#52616c; font-size:14px; transition:.2s ease; }
.option:hover { border-color:#81cdbc; background:#f4fcfa; transform:translateY(-1px); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.radio-mark { width:16px; height:16px; border:1.5px solid #b8c6cc; border-radius:50%; flex:none; position:relative; }
.option:has(input:checked) { background:#e9f9f4; border-color:#58b9a4; color:#145f55; font-weight:700; }
.option:has(input:checked) .radio-mark { border-color:var(--deep); }
.option:has(input:checked) .radio-mark:after { content:""; position:absolute; width:8px; height:8px; background:var(--deep); border-radius:50%; top:2.5px; left:2.5px; }
.quiz-footer { display:flex; justify-content:space-between; align-items:center; gap:20px; padding-top:27px; }
.status { color:#c05a53; font-size:13px; margin:0; min-height:18px; }
button { border:0; border-radius:10px; background:var(--deep); color:#fff; font:700 14px 'DM Sans',sans-serif; padding:14px 21px; cursor:pointer; box-shadow:0 5px 12px rgba(23,107,96,.2); transition:.2s; }
button:hover { background:#0e564e; transform:translateY(-1px); } button span { font-size:19px; vertical-align:-1px; margin-left:8px; }
.result { text-align:center; padding:34px 0 0; }
.score { color:var(--deep); font:700 55px 'Space Grotesk',sans-serif; line-height:1.1; margin-top:7px; }
.score small { font-size:20px; color:#9aabb1; font-weight:500; }
.result p { color:var(--muted); margin:5px 0 0; font-size:14px; }
@media (max-width:650px) { .app-shell { padding-top:38px; } .quiz-card { padding:4px 20px 22px; } .options { grid-template-columns:1fr; margin-left:0; gap:8px; } .question-heading { gap:11px; } h2 { font-size:17px; } .quiz-footer { align-items:flex-end; flex-direction:column; } button { width:100%; } }

application.javascript:
document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const status = document.getElementById('status');
  const scoreEl = document.querySelector('[data-testid="quiz-score"]');
  const scoreNumber = document.getElementById('score-number');
  const message = document.getElementById('result-message');
  const correct = ['Mars', 'Pacific Ocean', 'CSS'];

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const answers = correct.map(function (_, index) {
      const selected = form.querySelector('input[name="question-' + (index + 1) + '"]:checked');
      return selected ? selected.value : null;
    });
    if (answers.some(function (answer) { return answer === null; })) {
      status.textContent = 'Please answer all three questions first.';
      const firstMissing = answers.findIndex(function (answer) { return answer === null; });
      const target = form.querySelector('input[name="question-' + (firstMissing + 1) + '"]');
      if (target) target.closest('.question').scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    status.textContent = '';
    const score = answers.reduce(function (total, answer, index) {
      return total + (answer === correct[index] ? 1 : 0);
    }, 0);
    scoreEl.dataset.score = String(score);
    scoreNumber.textContent = String(score);
    message.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'A fresh start is always a good one.' : 'Nice work — keep exploring and learning.';
  });
});
